# Code for the manuscript Gordon, J.A., Kazlou, T., Jewell, J. and Cherp, A.
# First-of-a-Kind deployment prospects for small modular reactors
#
# Rebuilds Figure 3: probabilistic framework for SMR project progression,
# pipeline evolution and FOAK deployment.
#
# This master script reads the panel-level RDS objects generated by the
# Figure 3 panel scripts and assembles the final Figure 3.
#
# Required inputs:
# revision/outputs/Main_Figures/
#   fig03_panel_a_duration_distributions.rds
#   fig03_panel_b_project_progression.rds
#   fig03_panel_c_design_additions.rds
#   fig03_panel_d_failure_risks.rds
#   fig03_panels_e_f_future_pipeline.rds
#
# Outputs:
# revision/outputs/Main_Figures/
#   fig03_foak_framework.png
#   fig03_foak_framework.pdf
#   fig03_foak_framework.rds


suppressPackageStartupMessages({
  library(ggplot2)
  library(cowplot)
  library(grid)
})


rm(list = ls())
graphics.off()


# ============================================================
# FIGURE 3 — MASTER A-F REBUILD
# GITHUB-REPRODUCIBLE VERSION
# ============================================================


# ------------------------------------------------------------
# REPOSITORY ROOT
# ------------------------------------------------------------

find_repo_root <- function(start = getwd()) {
  
  current <- normalizePath(
    start,
    winslash = "/",
    mustWork = TRUE
  )
  
  repeat {
    
    revision_dir <- file.path(
      current,
      "revision"
    )
    
    data_dir <- file.path(
      revision_dir,
      "data",
      "Main_Figures"
    )
    
    scripts_dir <- file.path(
      revision_dir,
      "scripts",
      "Main_Figures"
    )
    
    if (
      dir.exists(revision_dir) &&
      dir.exists(data_dir) &&
      dir.exists(scripts_dir)
    ) {
      return(current)
    }
    
    parent <- dirname(current)
    
    if (identical(parent, current)) {
      
      stop(
        paste0(
          "Could not locate repository root.\n",
          "Expected repository structure containing:\n",
          "revision/data/Main_Figures/\n",
          "revision/scripts/Main_Figures/\n\n",
          "Start directory was: ",
          start,
          "\n\n",
          "Run this script from inside the GitHub repository."
        )
      )
    }
    
    current <- parent
  }
}


ROOT_DIR <- find_repo_root()


# ------------------------------------------------------------
# OUTPUT / INTERMEDIATE DIRECTORY
# ------------------------------------------------------------

OUT_DIR <- file.path(
  ROOT_DIR,
  "revision",
  "outputs",
  "Main_Figures"
)


dir.create(
  OUT_DIR,
  recursive = TRUE,
  showWarnings = FALSE
)


# ------------------------------------------------------------
# REQUIRED PANEL OBJECTS
# ------------------------------------------------------------

FILE_A <- file.path(
  OUT_DIR,
  "fig03_panel_a_duration_distributions.rds"
)


FILE_B <- file.path(
  OUT_DIR,
  "fig03_panel_b_project_progression.rds"
)


FILE_C <- file.path(
  OUT_DIR,
  "fig03_panel_c_design_additions.rds"
)


FILE_D <- file.path(
  OUT_DIR,
  "fig03_panel_d_failure_risks.rds"
)


FILE_EF <- file.path(
  OUT_DIR,
  "fig03_panels_e_f_future_pipeline.rds"
)


required_files <- c(
  FILE_A,
  FILE_B,
  FILE_C,
  FILE_D,
  FILE_EF
)


# ------------------------------------------------------------
# CHECK REQUIRED PANEL OBJECTS
# ------------------------------------------------------------

missing_files <- required_files[
  !file.exists(required_files)
]


if (length(missing_files) > 0) {
  
  stop(
    paste0(
      "Missing required Figure 3 intermediate RDS file(s):\n",
      paste(
        missing_files,
        collapse = "\n"
      ),
      "\n\n",
      "Run the corresponding Figure 3 panel script(s) first."
    )
  )
}


# ------------------------------------------------------------
# EXPORT SETTINGS
# ------------------------------------------------------------

SAVE_W_MM <- 180
SAVE_H_MM <- 230
SAVE_DPI  <- 600

FILE_STUB <- "fig03_foak_framework"


# ------------------------------------------------------------
# SCENARIO COLOURS
# ------------------------------------------------------------

col_reference_line     <- "grey30"
col_proliferation_line <- "#006400"


# ------------------------------------------------------------
# READ PANEL OBJECTS
# ------------------------------------------------------------

panel_a <- readRDS(
  FILE_A
)


panel_b <- readRDS(
  FILE_B
)


panel_c <- readRDS(
  FILE_C
)


panel_d <- readRDS(
  FILE_D
)


panels_ef <- readRDS(
  FILE_EF
)


# ------------------------------------------------------------
# BUILD PANEL ROW A-B
# ------------------------------------------------------------

fig_ab <- plot_grid(
  panel_a,
  panel_b,
  ncol = 2,
  align = "hv",
  axis = "tblr",
  rel_widths = c(
    1,
    1.18
  )
)


# ------------------------------------------------------------
# BUILD PANEL ROW C-D
# ------------------------------------------------------------

fig_cd <- plot_grid(
  panel_c,
  panel_d,
  ncol = 2,
  align = "hv",
  axis = "tblr",
  rel_widths = c(
    1,
    1.18
  )
)


# ------------------------------------------------------------
# BUILD MASTER A-F
# ------------------------------------------------------------

fig_abcdef <- plot_grid(
  fig_ab,
  fig_cd,
  panels_ef,
  ncol = 1,
  align = "v",
  axis = "lr",
  rel_heights = c(
    72,
    72,
    86
  )
)


# ------------------------------------------------------------
# SHARED SCENARIO LEGEND
# ------------------------------------------------------------

scenario_df <- data.frame(
  
  x = c(
    1,
    2
  ),
  
  xend = c(
    2,
    3
  ),
  
  y = c(
    1,
    1
  ),
  
  yend = c(
    1,
    1
  ),
  
  lab = factor(
    c(
      "Reference",
      "Proliferation"
    ),
    levels = c(
      "Reference",
      "Proliferation"
    )
  )
)


scenario_legend_plot <- ggplot(
  scenario_df,
  aes(
    x = x,
    xend = xend,
    y = y,
    yend = yend,
    colour = lab
  )
) +
  
  geom_segment(
    linewidth = 1
  ) +
  
  scale_colour_manual(
    name = "Scenario",
    values = c(
      "Reference" = col_reference_line,
      "Proliferation" = col_proliferation_line
    ),
    breaks = c(
      "Reference",
      "Proliferation"
    )
  ) +
  
  guides(
    colour = guide_legend(
      nrow = 1,
      byrow = TRUE,
      override.aes = list(
        linewidth = 1.2
      )
    )
  ) +
  
  theme_void(
    base_size = 7
  ) +
  
  theme(
    
    legend.position = "bottom",
    
    legend.direction = "horizontal",
    
    legend.title = element_text(
      size = 6.5,
      face = "plain",
      colour = "black"
    ),
    
    legend.text = element_text(
      size = 6,
      colour = "black"
    ),
    
    legend.key.width = unit(
      8,
      "mm"
    ),
    
    legend.key.height = unit(
      3.5,
      "mm"
    ),
    
    legend.spacing.x = unit(
      2,
      "mm"
    ),
    
    legend.box.spacing = unit(
      0,
      "mm"
    ),
    
    legend.margin = margin(
      0,
      0,
      0,
      0
    )
  )


legend_scenario <- cowplot::get_legend(
  scenario_legend_plot
)


# ------------------------------------------------------------
# FINAL FIGURE
# ------------------------------------------------------------

fig_final <- plot_grid(
  fig_abcdef,
  legend_scenario,
  ncol = 1,
  rel_heights = c(
    1,
    0.035
  )
)


print(
  fig_final
)


# ------------------------------------------------------------
# OUTPUT FILES
# ------------------------------------------------------------

PNG_FILE <- file.path(
  OUT_DIR,
  paste0(
    FILE_STUB,
    ".png"
  )
)


PDF_FILE <- file.path(
  OUT_DIR,
  paste0(
    FILE_STUB,
    ".pdf"
  )
)


RDS_FILE <- file.path(
  OUT_DIR,
  paste0(
    FILE_STUB,
    ".rds"
  )
)


# ------------------------------------------------------------
# SAVE FINAL FIGURE
# ------------------------------------------------------------

ggsave(
  filename = PNG_FILE,
  plot = fig_final,
  width = SAVE_W_MM,
  height = SAVE_H_MM,
  units = "mm",
  dpi = SAVE_DPI,
  bg = "white",
  limitsize = FALSE
)


ggsave(
  filename = PDF_FILE,
  plot = fig_final,
  width = SAVE_W_MM,
  height = SAVE_H_MM,
  units = "mm",
  bg = "white",
  limitsize = FALSE,
  useDingbats = FALSE
)


saveRDS(
  fig_final,
  file = RDS_FILE
)


# ------------------------------------------------------------
# CONFIRM OUTPUTS
# ------------------------------------------------------------

cat(
  "\nFigure 3 master successfully assembled.\n\n"
)


cat(
  "Repository root:\n",
  ROOT_DIR,
  "\n\n"
)


cat(
  "Inputs:\n",
  paste(
    required_files,
    collapse = "\n"
  ),
  "\n\n"
)


cat(
  "Outputs:\n",
  PNG_FILE,
  "\n",
  PDF_FILE,
  "\n",
  RDS_FILE,
  "\n"
)


fig_final